        "pregunta":  "Eneritz trabaja como funcionaria en el Departamento de Salud del Gobierno Vasco desde hace 5 años. Durante este tiempo, ha desempeñado tareas administrativas en diversos puestos, pero hace un mes fue promovida a un puesto de jefa de unidad. En este nuevo rol, Eneritz se enfrenta a un proceso de revisión de la carrera profesional y se le ha informado de la existencia de un plan de formación y de movilidad en el empleo público vasco, como parte de su desarrollo. Eneritz está considerando solicitar una movilidad hacia otro puesto dentro de la Administración local, pues cree que ese cambio le permitirá continuar su carrera profesional y mejorar su experiencia en otras áreas. Sin embargo, tiene dudas sobre si su solicitud será viable y sobre los derechos que le corresponderían durante este proceso. Según la Ley de Empleo Público Vasco, ¿cómo debe proceder Eneritz para solicitar su movilidad hacia otro puesto en la Administración local? ¿Cuáles son las implicaciones de este proceso y qué derechos mantendría durante el mismo?",
