        "numero_temario":  485,
        "pregunta":  "Durante el ejercicio 2025, la sociedad SAKI, S.A., cuya actividad principal es la fabricación de maquinaria destinada a centros hospitalarios, experimento una notable caída como consecuencia de una reducción en los presupuestos destinados a sanidad. Como resultado, el 31 de enero de 2026 se puso en marcha un plan de desinversión y reorientación de sus líneas productivas. En el marco de dicho plan, la entidad decidió desprenderse de ciertos elementos del inmovilizado con menor aportación al negocio y concentrarse en las áreas con mayor rendimiento. Entre las decisiones adoptadas se encuentran: i. transmisión de algunas máquinas a una compañía situada en las proximidades de las instalaciones de SAKI, S.A.; y ii. venta de solares adquiridos en el momento de constitución de la sociedad (finales del año 2000) a un grupo inmobiliario. Del Balance de Situación cerrado a 31 de diciembre de 2025, y tomando los importes en Valor Neto Contable (VNC), se dispone de los siguientes datos: • Maquinas:1.776.000€; y • Solares: 2.440.000€. Las máquinas comenzaron a utilizarse el 1 de enero de 2023, se amortizan por el método lineal, tienen una vida útil estimada de 8 años y su valor residual es cero. Por su parte, los solares han permanecido en el patrimonio de OSAKI, S.A. desde su constitución, a finales del año 2000. Las operaciones de venta se formalizan el 31 de enero de 2026 mediante efectos comerciales aceptados por los compradores, por importes de 1.776.000€ en el caso de las máquinas vendidas y de 1.280.000€ en el caso de los solares. NOTA: Las operaciones deben considerarse exentas de IVA a efectos de los cálculos. ¿Qué pérdida contable generó la venta de los solares?",
